import os
import torch


class CFG:
    """
    Configuration class for Apple Disease Detection.
    Implements the Heterogeneous Dual-Backbone Ensemble strategy.
    """

    # ==========================
    # General Configuration
    # ==========================
    seed = 42
    debug = False  # Set to True to restrict dataset size for faster debugging
    num_workers = 4

    # ==========================
    # Data Paths
    # ==========================
    input_root = "./input"

    # Metadata files (generated by the provided script)
    train_csv = "./metadata/train.csv"
    val_csv = "./metadata/val.csv"
    test_csv = "./metadata/test.csv"

    # Image directories
    train_images_dir = os.path.join(input_root, "train_images")
    test_images_dir = os.path.join(input_root, "test_images")

    # ==========================
    # Output Directories
    # ==========================
    working_dir = "./working/idea_3"
    output_dir = working_dir
    submission_dir = "./submission"
    submission_path = os.path.join(submission_dir, "submission.csv")

    # ==========================
    # Dataset Parameters
    # ==========================
    img_size = 384
    num_classes = 6

    # Labels sorted alphabetically (standard behavior for MultiLabelBinarizer)
    # Based on data analysis: ['complex', 'frog_eye_leaf_spot', 'healthy', 'powdery_mildew', 'rust', 'scab']
    class_labels = [
        "complex",
        "frog_eye_leaf_spot",
        "healthy",
        "powdery_mildew",
        "rust",
        "scab",
    ]

    # ==========================
    # Model Architecture
    # ==========================
    # Heterogeneous Dual-Backbone Ensemble
    # 1. ConvNeXt-Base: Scaled up CNN with LayerNorm design
    # 2. Swin V2-Base: Hierarchical Transformer with shifted windows
    backbones = [
        "convnext_base.fb_in22k_ft_in1k_384",
        "swinv2_base_window12to24_192to384.ms_in22k_ft_in1k",
    ]

    # Head design
    pooling = "gem"  # Generalized Mean Pooling

    # ==========================
    # Training Hyperparameters
    # ==========================
    epochs = 25

    # Batch Size Strategy for 40GB VRAM
    # Base models at 384x384 are memory intensive.
    # Physical batch size 4 * Gradient Accumulation 8 = Effective Batch Size 32
    batch_size = 4
    gradient_accumulation_steps = 8

    # Optimizer
    lr = 2e-4
    weight_decay = 1e-2
    min_lr = 1e-6
    eps = 1e-6

    # Scheduler
    scheduler = "CosineAnnealingLR"
    T_max = epochs

    # Loss
    loss_fn = "BCEWithLogitsLoss"

    # ==========================
    # Augmentation
    # ==========================
    # CoarseDropout for regularization
    coarse_dropout_prob = 0.5

    # ==========================
    # Inference
    # ==========================
    tta = True  # Test Time Augmentation (Horizontal Flip)

    # ==========================
    # Hardware
    # ==========================
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")

    @classmethod
    def setup(cls):
        """Creates necessary working and submission directories."""
        os.makedirs(cls.working_dir, exist_ok=True)
        os.makedirs(cls.submission_dir, exist_ok=True)


# Initialize directories
CFG.setup()
